// The language Kobble speaks on this computer: English, Italian or German,
// or the browser's. Each person's own (the personal settings file, never
// team.env), chosen in Settings › Language. The kobolds answer in the
// language the dashboard shows.
import { readSettings } from "../parts/addresses.js";
import { saveGroup } from "../settings/setting-groups.js";
import { PERSONAL_FILE } from "../settings/team-file.js";
export const LANGUAGES = ["en", "it", "de"];
export const LANGUAGE_KEY = "FACTORY_LANGUAGE";
// Kept with the other settings, but not shown as a settings group: the
// dashboard has its own choice for it.
export const languageSettings = {
    id: "language",
    name: "Language",
    about: "The language Kobble speaks on this computer.",
    file: PERSONAL_FILE,
    usedBy: [],
    fields: [
        {
            key: LANGUAGE_KEY,
            label: "Language",
            help: "English, Italiano or Deutsch; or the browser's language.",
            kind: "choice",
            default: "browser",
            choices: [
                { value: "browser", label: "As the browser" },
                { value: "en", label: "English" },
                { value: "it", label: "Italiano" },
                { value: "de", label: "Deutsch" },
            ],
        },
    ],
};
export function isLanguageChoice(value) {
    return value === "browser" || LANGUAGES.some((one) => one === value);
}
export function languageChoice(root) {
    const saved = readSettings(root, languageSettings.file)[LANGUAGE_KEY];
    return isLanguageChoice(saved) ? saved : "browser";
}
export function chooseLanguage(root, choice) {
    saveGroup(languageSettings, root, { [LANGUAGE_KEY]: choice });
}
// The language's name in English, for the kobolds' instructions.
const NAMES = {
    en: "English",
    it: "Italian (italiano)",
    de: "German (Deutsch)",
};
// What a kobold is told about the language to answer in; nothing for
// English, which its instructions are written in.
export function answerIn(language) {
    if (language === "en")
        return "";
    return `\n\n## Language\n\nThe team reads Kobble in ${NAMES[language]}. Answer them in ${NAMES[language]}, plainly, in the same short style. Keep file names, code, ids, commands and quotes from the app as they are.`;
}
